{"path": "/app/tests/test_money.py", "content": """"The rounding rules of meterbill.money."""

import math
import unittest
from decimal import Decimal
from fractions import Fraction

from meterbill import money
from meterbill.money import CENT, DOWN, HALF_EVEN, HALF_UP, allocate, fixed, legacy_cents, round_amount


def D(s: str) -> Decimal:
    return Decimal(s)


class RoundAmount(unittest.TestCase):
    def test_ties(self):
        self.assertEqual(round_amount(D("0.125"), CENT, HALF_UP), D("0.13"))
        self.assertEqual(round_amount(D("0.125"), CENT, HALF_EVEN), D("0.12"))
        self.assertEqual(round_amount(D("0.135"), CENT, HALF_EVEN), D("0.14"))
        self.assertEqual(round_amount(D("-0.125"), CENT, HALF_UP), D("-0.13"))
        self.assertEqual(round_amount(D("-0.125"), CENT, HALF_EVEN), D("-0.12"))
        self.assertEqual(round_amount(D("0.129"), CENT, DOWN), D("0.12"))
        self.assertEqual(round_amount(D("-0.129"), CENT, DOWN), D("-0.12"))

    def test_other_steps(self):
        self.assertEqual(round_amount(D("12.325"), D("0.05"), HALF_UP), D("12.35"))
        self.assertEqual(round_amount(D("12.325"), D("0.05"), HALF_EVEN), D("12.30"))
        self.assertEqual(round_amount(D("12.375"), D("0.05"), HALF_EVEN), D("12.40"))
        self.assertEqual(round_amount(D("1234.5"), D("1"), HALF_EVEN), D("1234"))
        self.assertEqual(round_amount(D("0.00015"), D("0.0001"), HALF_UP), D("0.0002"))

    def test_exponent_of_step(self):
        self.assertEqual(str(round_amount(D("7"), D("0.05"), HALF_UP)), "7.00")
        self.assertEqual(str(round_amount(D("7.6"), D("1"), HALF_UP)), "8")
        self.assertEqual(str(round_amount(D("7"), D("0.10"), HALF_UP)), "7.00")
        self.assertEqual(str(round_amount(D("7"), D("0.0001"), DOWN)), "7.0000")

    def test_sign_of_zero_is_kept(self):
        self.assertEqual(str(round_amount(D("-0.001"), CENT, HALF_UP)), "-0.00")
        self.assertEqual(str(round_amount(D("0.001"), CENT, HALF_UP)), "0.00")

    def test_big_values_are_exact(self):
        v = D("123456789012345678901234567890123.455")
        self.assertEqual(round_amount(v, CENT, HALF_UP), D("123456789012345678901234567890123.46"))
        self.assertEqual(round_amount(v, CENT, HALF_EVEN), D("123456789012345678901234567890123.46"))
        self.assertEqual(round_amount(D("1E+40"), CENT, DOWN), D("1E+40"))

    def test_matches_exact_arithmetic(self):
        for n in range(-300, 301):
            value = D(n) / D(40)
            for step in (D("0.05"), D("0.1"), D("1"), D("0.25")):
                exact = Fraction(value) / Fraction(step)
                floor = math.floor(abs(exact))
                frac = abs(exact) - floor
                up = floor + (1 if frac >= Fraction(1, 2) else 0)
                even = floor + (1 if frac > Fraction(1, 2) or (frac == Fraction(1, 2) and floor % 2) else 0)
                sign = -1 if exact < 0 else 1
                for method, m in ((HALF_UP, up), (HALF_EVEN, even), (DOWN, floor)):
                    self.assertEqual(Fraction(round_amount(value, step, method)), sign * m * Fraction(step))

    def test_errors(self):
        with self.assertRaises(TypeError):
            round_amount(1.5, CENT, HALF_UP)
        with self.assertRaises(TypeError):
            round_amount(D("1"), "0.01", HALF_UP)
        with self.assertRaises(ValueError):
            round_amount(D("1"), CENT, "up")
        for bad in (D("0"), D("-0.01")):
            with self.assertRaises(ValueError):
                round_amount(D("1"), bad, HALF_UP)


class Allocate(unittest.TestCase):
    def test_remainder_goes_to_the_last_charged_segment(self):
        got = allocate([D("5.3469"), D("7.8966")], CENT)
        self.assertEqual(got, [D("5.34"), D("7.90")])
        self.assertEqual(allocate([D("0.0049"), D("0.0049"), D("0")], CENT), [D("0.00"), D("0.01"), D("0.00")])

    def test_sums_to_the_rounded_whole(self):
        amounts = [D("1.0049"), D("2.0049"), D("3.0049"), D("0.0047")]
        for step in (CENT, D("0.05"), D("1"), D("0.0001")):
            got = allocate(amounts, step)
            self.assertEqual(sum(got), round_amount(sum(amounts), step, HALF_UP))
            for part in got:
                self.assertEqual(part, round_amount(part, step, HALF_UP))

    def test_input_unchanged_and_empty(self):
        amounts = [D("1.239"), D("1.239")]
        allocate(amounts, CENT)
        self.assertEqual(amounts, [D("1.239"), D("1.239")])
        self.assertEqual(allocate([], CENT), [])

    def test_negative_amounts(self):
        got = allocate([D("-1.239"), D("-1.239")], CENT)
        self.assertEqual(got, [D("-1.23"), D("-1.25")])


class LegacyCents(unittest.TestCase):
    def test_settle(self):
        self.assertEqual(legacy_cents(4.256), 4.26)
        self.assertEqual(legacy_cents(-4.25), -4.25)
        self.assertEqual(legacy_cents(-0.005), 0.0)
        self.assertEqual(legacy_cents(2.675), 2.68)

    def test_places(self):
        for x in (0.5, 1.5, 2.5, -2.5, 1.2345, 0.0000005):
            for places in range(7):
                scale = 10**places
                self.assertEqual(legacy_cents(x, places), math.floor(x * scale + 0.5) / scale)
        self.assertEqual(legacy_cents(2.5, 0), 3.0)
        self.assertEqual(legacy_cents(1.23456, 3), 1.235)

    def test_places_range(self):
        for bad in (-1, 7):
            with self.assertRaises(ValueError):
                legacy_cents(1.0, bad)


class Fixed(unittest.TestCase):
    def test_float_is_python_formatting(self):
        self.assertEqual(fixed(2.675, 2), "2.67")
        self.assertEqual(fixed(0.125, 2), "0.12")
        self.assertEqual(fixed(0.375, 2), "0.38")
        self.assertEqual(fixed(2.5, 0), "2")
        self.assertEqual(fixed(-0.001, 2), "-0.00")
        self.assertEqual(fixed(1e22, 1), "10000000000000000000000.0")
        for x in (0.5, 1.005, 123.456, -7.25, 3.0):
            for places in range(5):
                self.assertEqual(fixed(x, places), format(x, "." + str(places) + "f"))

    def test_float_other_method(self):
        with self.assertRaises(ValueError):
            fixed(1.5, 1, HALF_UP)
        with self.assertRaises(ValueError):
            fixed(1.5, 1, DOWN)

    def test_decimal(self):
        self.assertEqual(fixed(D("0.125"), 2), "0.12")
        self.assertEqual(fixed(D("0.125"), 2, HALF_UP), "0.13")
        self.assertEqual(fixed(D("0.129"), 2, DOWN), "0.12")
        self.assertEqual(fixed(D("20.5"), 0, HALF_UP), "21")
        self.assertEqual(fixed(D("20.5"), 0), "20")
        self.assertEqual(fixed(D("0.061650"), 4, HALF_UP), "0.0617")
        self.assertEqual(fixed(D("0.06165"), 4), "0.0616")
        self.assertEqual(fixed(D("5"), 3), "5.000")
        self.assertEqual(fixed(D("0.0005"), 2), "0.00")
        self.assertEqual(fixed(D("-0.004"), 2), "-0.00")

    def test_decimal_is_never_in_exponent_notation(self):
        self.assertEqual(fixed(D("1E+30"), 2), "1" + "0" * 30 + ".00")
        self.assertEqual(fixed(D("1E-30"), 2), "0.00")
        self.assertEqual(fixed(D("12345678901234567890123456789012.345"), 2, HALF_UP), "12345678901234567890123456789012.35")


class Module(unittest.TestCase):
    def test_public_names(self):
        public = {n for n in dir(money) if not n.startswith("_")}
        self.assertEqual(
            public & {"CENT", "HALF_UP", "HALF_EVEN", "DOWN", "round_amount", "allocate", "legacy_cents", "fixed"},
            {"CENT", "HALF_UP", "HALF_EVEN", "DOWN", "round_amount", "allocate", "legacy_cents", "fixed"},
        )
        self.assertEqual(CENT, D("0.01"))
        self.assertEqual(str(CENT), "0.01")


